    s_idle = "[idle]" if self.idle.is_set() else "[busy]"
    s_cache_length = f"[cache size: {len(self.history)}]"
    s_running = f"[running: {self.running}]"
    s = f"{self.__class__.__name__} {s_running} {s_idle} {s_cache_length}>"
    return s

